const fs = require('fs');
const path = require('path');

// ============================================================
// generar_464_detalles_chat.js
// ============================================================
// Dos cosas que quedaron sueltas.
//
// 1. CONCORDANCIA
//    Decia "No tengo vacunas anotadOS". Ahora "anotadas" para vacunas y
//    "anotados" para antiparasitarios, cada uno con su genero.
//
// 2. UN CUIDADO QUE TODAVIA NO SE REGISTRA
//    En una mascota nueva, "¿hace cuanto lo bañe?" respondia "no estoy
//    segura de que quieres consultar" — que suena a que no entendio,
//    cuando si entendio: simplemente no hay nada anotado.
//
//    Ahora dice:
//      "Todavía no tengo baños registrados de Nuevo.
//       Se anotan en el registro diario, en la fila de piel y aseo. Con
//       dos o más ya puedo decirte cada cuánto los sueles hacer."
//
// UN ERROR QUE COMETI Y CORREGI
// La primera version de esto iba ANTES de la clasificacion, y la raiz
// "unas" esta dentro de "vacUNAS": preguntar por vacunas respondia
// sobre el corte de uñas. Es el MISMO bug que ya habiamos arreglado, y
// lo reintroduje al agregar codigo antes de tiempo.
//
// Ahora el bloque va AL FINAL, donde solo se llega si ninguna categoria
// calzo. Ahi no le puede robar nada a nadie.
//
// REQUISITO: script 461 desplegado.
//
// Si algo no calza, ABORTA sin escribir.
// ============================================================

const RUTA = 'components/ChiquiChat.tsx';
const CHAT_B64 = '';

function abortar(motivo) {
  console.log('');
  console.log('ABORTADO: ' + motivo);
  console.log('No se modifico ningun archivo. Avisale a Claude lo que dice este mensaje.');
  process.exit(1);
}

const destino = path.join(process.cwd(), RUTA);
if (!fs.existsSync(destino)) {
  abortar('no se encontro ' + RUTA + '.');
}

const actual = fs.readFileSync(destino, 'utf8');
if (actual.includes('CUIDADOS_CONOCIDOS')) {
  abortar('el chat ya tiene estos detalles. Parece que este script ya se corrio.');
}
if (!actual.includes('const PERIODOS')) {
  abortar('falta el script 461. Correlo primero.');
}

const comp = Buffer.from(CHAT_B64, 'base64').toString('utf8');

const REQUERIDOS = [
  "'use client'", 'export default function ChiquiChat',
  'CUIDADOS_CONOCIDOS', 'vacunas anotadas', 'antiparasitarios anotados',
  'Todavía no tengo', 'const PERIODOS', 'mascotaId?: string',
];
for (const r of REQUERIDOS) {
  if (!comp.includes(r)) {
    abortar('el contenido nuevo no incluye [' + r + ']. Script corrupto, no se escribio nada.');
  }
}

// EL BLOQUE DE CUIDADOS TIENE QUE IR DESPUES DE LA CLASIFICACION.
// Si quedara antes, "unas" capturaria "vacUNAS" — el bug que ya
// arreglamos una vez.
const posCuidados = comp.indexOf('CUIDADOS_CONOCIDOS');
const posClasif = comp.indexOf('// --- 5. LA INTENCIÓN QUE MÁS COINCIDE ---');
if (posCuidados < posClasif) {
  abortar('el bloque de cuidados quedaria ANTES de la clasificacion: robaria las preguntas de vacunas.');
}
console.log('  OK  el bloque de cuidados va despues de la clasificacion');
console.log('  OK  el contenido nuevo esta completo');

fs.writeFileSync(destino, comp, 'utf8');
console.log('');
console.log('OK: ' + RUTA);
console.log('');
console.log('Listo.');
